bun run .aidd/gen-features.ts && echo "---validate deps---" && bun -e '
import { readdirSync, readFileSync } from "node:fs";
const dir=".aidd/features";
const ids=new Set(readdirSync(dir));
let ok=true;
for(const id of ids){
  const f=JSON.parse(readFileSync(`${dir}/${id}/feature.json","utf8"));
  if(f.id!==id){console.log("DIR/ID MISMATCH",id,f.id);ok=false;}
  for(const d of f.dependencies){if(!ids.has(d)){console.log("BAD DEP",id,"->",d);ok=false;}}
}
console.log("total features:",ids.size, ok?"ALL DEPS VALID":"ERRORS");
'

bun -e '
import { readdirSync, readFileSync } from "node:fs";
const dir = ".aidd/features";
const ids = new Set(readdirSync(dir));
let ok = true;
for (const id of ids) {
  const f = JSON.parse(readFileSync(dir + "/" + id + "/feature.json", "utf8"));
  if (f.id !== id) { console.log("DIR/ID MISMATCH", id, f.id); ok = false; }
  for (const d of f.dependencies) { if (!ids.has(d)) { console.log("BAD DEP", id, "->", d); ok = false; } }
}
console.log("total features:", ids.size, ok ? "ALL DEPS VALID" : "ERRORS");
'
